from fastapi.responses import HTMLResponse
HTML='''<!doctype html><html><head><meta charset="utf-8"><title>Personal AI Control</title><style>body{margin:0;background:#050608;color:#eef4f8;font:14px system-ui}header{padding:24px 32px;border-bottom:1px solid #1a2630}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;padding:24px}.card{background:#0b0f14;border:1px solid #1d2b36;border-radius:18px;padding:20px;min-height:110px}.wide{grid-column:span 2}input,button{background:#101822;color:#eef4f8;border:1px solid #294052;border-radius:10px;padding:10px}.muted{color:#8295a3}.big{font-size:28px}pre{white-space:pre-wrap;max-height:300px;overflow:auto}@media(max-width:800px){.grid{grid-template-columns:1fr}.wide{grid-column:span 1}}</style></head><body><header><b>PERSONAL AI</b> <span class=muted>Control Dashboard</span><div style="float:right"><input id=d placeholder="device id"><input id=t type=password placeholder="bearer token"><button onclick=save()>Connect</button></div></header><main class=grid><div class=card><div class=muted>Devices</div><div class=big id=devices>-</div></div><div class=card><div class=muted>Automations</div><div class=big id=automations>-</div></div><div class=card><div class=muted>Memory nodes</div><div class=big id=memory>-</div></div><div class=card><div class=muted>Voice</div><div class=big id=voice>-</div></div><div class="card wide"><b>Integrations</b><pre id=integrations></pre></div><div class="card wide"><b>Security / Runtime</b><pre id=security></pre></div></main><script>function save(){sessionStorage.d=d.value;sessionStorage.t=t.value;load()}async function api(p){let r=await fetch('/dashboard/'+p,{headers:{Authorization:'Bearer '+sessionStorage.t,'X-Device-ID':sessionStorage.d}});if(!r.ok)throw Error(await r.text());return r.json()}async function load(){try{let s=await api('status');devices.textContent=s.devices;automations.textContent=s.automations;memory.textContent=s.memory_nodes;voice.textContent=s.voice_state||'idle';integrations.textContent=JSON.stringify(s.integrations,null,2);security.textContent=JSON.stringify(s.security,null,2)}catch(e){security.textContent=e}}setInterval(load,5000);if(sessionStorage.d)load()</script></body></html>'''
def dashboard_html():return HTMLResponse(HTML)
